import logging
import os
import shutil
import subprocess
import zipfile
from subprocess import CalledProcessError
from itertools import cycle

import requests
from taf.sbts.oam.coam.admin import admin
from taf.rfrl.uuf4all.resources.python.uuf_rfrl_utilities import robot_logger, set_robot_test_variable, robot_var
admin = admin()


class uuf_rfrl_update:

    def __init__(self):
        self.access_key = "gKfr58ELsV5hdaBapwizQxhmBd9UR3Ndda0mbgvC"
        self.artifactory_key = "AKCp8oiHU5YPce4g24nY4H9XxoVHAVzcydFrggjst4Ym8FPW7jnEnLDyTDbkNk6ma5XV2NC95"
        self.wft_url = "https://wft.int.net.nokia.com:8091/api/v1/"

    def get_download_link(self, sw_version, test_package=False):
        valid_test_package_values = {"T1", "T2", False}
        if test_package not in valid_test_package_values:
            raise ValueError("Wrong test_package value! Acceptable values: {}".format(valid_test_package_values))
        branch = sw_version.split("_")[0]
        endpoint = "{0}/CI_ENB/builds/{1}/storages/results.json?access_key={2}".format(branch, sw_version,
                                                                                       self.access_key)
        response = requests.get(url=self.wft_url + endpoint).json()
        files_list = response[0]["storage"]["storage-items"]
        download_link = ""
        if "5G" in branch:
            if test_package:
                file_name = "AirScale-{}{}.zip".format(sw_version.split("_", 1)[1], test_package)
            else:
                file_name = "AirScale-{}.zip".format(sw_version.split("_", 1)[1])
            dw_link = [item["path"] for item in files_list if item["title"] == file_name]
            download_link = dw_link[0]
        elif "SBTS" in branch:
            if test_package:
                file_name = ("{}_release_BTSSM_downloadable_testpackage_{}_A54.zip".format(sw_version, test_package))
            else:
                file_name = "{}_release_BTSSM_downloadable_A54.zip".format(sw_version)
            download_link = [file_.get("path") for storage in response
                             for file_ in storage["storage"].get("storage-items") if
                             file_name in file_["title"] and
                             any(artifactory in file_.get("path")
                                 for artifactory in ["lterel.es-si-s3-z4",
                                                     "https://artifactory-espoo2.int.net.nokia.com"])][0]
        return download_link

    @staticmethod
    def get_sw_branch(sw_version=None):
        branch = sw_version.split("_")[0]
        if branch == "5G21A":
            branch = "21A_classicalbts"
        elif str(sw_version.split("_", 3)[2]) == "9999":
            branch = "SBTS00"
        else:
            branch = sw_version.split("_")[0]

        return branch

    def update_to_specific_sw(self, sw_version, test_package=False, connection=''):
        """
        Update software to specific one.
        :param sw_version: string with specific software version
        :param test_package: True if should be updated as test package; default: False
        :param connection: alias for already setup TAF admin
        """
        path_to_file = self.download_package(sw_version, test_package)
        admin.update_software(sw_package=path_to_file, timeout=3600, should_activate=True, alias=connection)

    def download_package(self, sw_version, test_package=False, use_builds_storage=True, download_path=None):
        """
        Download .zip package with specified software version to the given directory.
        :param sw_version: string with specified software version
        :param test_package: "T1"/"T2"/False
        :param use_builds_storage: True/False
        :param download_path: custom download path
        :return: path to the directory with downloaded package file
        """
        branch = self.get_sw_branch(sw_version)
        download_dir = self._get_download_dir(branch, use_builds_storage, download_path)
        if not use_builds_storage and not os.path.exists(download_dir):
            os.mkdir(download_dir)
        if download_path:
            local_file_path = os.path.join(download_path, f"{sw_version}_release_BTSSM_downloadable_A54.zip")
            robot_logger(f"Using as local file path: {local_file_path}")
            return local_file_path
        link_to_file = self.get_download_link(sw_version, test_package)
        local_file_path = self.get_local_file_path(link_to_file.split("/")[-1], download_dir)
        wft_file_size = int(requests.get(url=link_to_file, stream=True, timeout=120).headers.get('Content-Length'))
        if local_file_path:
            local_file_size = int(os.path.getsize(local_file_path))
        if local_file_path and wft_file_size == local_file_size:
            robot_logger("{} file already downloaded to {}".format(link_to_file.split("/")[-1], local_file_path),
                         "info")
        else:
            local_file_path = "/".join([download_dir, link_to_file.split("/")[-1]])
            with requests.get(url=link_to_file, stream=True, timeout=120,
                              headers={"X-JFrog-Art-Api": self.artifactory_key}) as request:
                if request.status_code == 200:
                    robot_logger("Downloading a {} file to {}".format(link_to_file.split("/")[-1], download_dir),
                                 "info")
                    with open(local_file_path, "wb") as f:
                        shutil.copyfileobj(request.raw, f, length=16 * 1024 * 1024)
                else:
                    raise Exception("'get' request error")
        return local_file_path.strip()

    @staticmethod
    def get_local_file_path(file_name, download_dir):
        path = None
        try:
            path = subprocess.check_output("find {}/* -name '{}'".format(download_dir, file_name), shell=True,
                                           universal_newlines=True).strip()
        except CalledProcessError:
            logging.debug("File {} does not exist in {}".format(file_name, download_dir))

        return path

    def mount_sw_dir(self):
        sw_dir = self._get_sw_dir(use_builds_storage=True)
        if not os.path.exists(os.path.join(sw_dir, 'SBTS')):
            if not os.path.exists(sw_dir):
                cmd = r"sudo mkdir /mnt/UUF_SW &&" \
                      r"sudo chmod 777 /mnt/UUF_SW &&" \
                      r"sudo mount -t cifs //10.42.248.45/Global_veryfication/[1]\ SW /mnt/UUF_SW/ -o" \
                      r" username=wro5grrm,password='5gpass!1'" \
                      r",domain=noklab,file_mode=0777,dir_mode=0777,uid=ute,gid=ute"
            else:
                cmd = r"sudo mount -t cifs //10.42.248.45/Global_veryfication/[1]\ SW /mnt/UUF_SW/ -o" \
                      r" username=wro5grrm,password='5gpass!1'" \
                      r",domain=noklab,file_mode=0777,dir_mode=0777,uid=ute,gid=ute"
            try:
                subprocess.check_output(cmd, universal_newlines=True, shell=True)
            except subprocess.CalledProcessError as e:
                print(str(e), e.returncode, e.output)
                raise Exception(e)

    @staticmethod
    def _get_sw_dir(use_builds_storage=True, download_path=None):
        if use_builds_storage:
            return '/mnt/UUF_SW/'
        elif not use_builds_storage and download_path is not None:
            return download_path
        return '/home/ute/UUF_SW/'

    def _get_download_dir(self, branch, use_builds_storage=True, download_path=None):
        sw_dir = self._get_sw_dir(use_builds_storage=use_builds_storage, download_path=download_path)
        download_dir = sw_dir
        if use_builds_storage:
            if "SBTS" in branch:
                download_dir = sw_dir + "SBTS/" + branch
            elif "21A" in branch:
                download_dir = sw_dir + "gNB/5G21A"
        return download_dir

    def download_test_packages(self, node_tech, sw_version, use_builds_storage=True, download_path=None):
        t1_path = self.download_package(sw_version, "T1", use_builds_storage, download_path)
        t2_path = self.download_package(sw_version, "T2", use_builds_storage, download_path)
        set_robot_test_variable("{}_TARGET_T1_SW_PATH".format(node_tech), t1_path)
        set_robot_test_variable("{}_TARGET_T2_SW_PATH".format(node_tech), t2_path)
        self.prepare_sw_iterator(node_tech)
        return t1_path, t2_path

    @staticmethod
    def get_sw_name_from_sw_package(sw_package_path):
        sw_file_zip = zipfile.ZipFile(sw_package_path)
        files = sw_file_zip.namelist()
        for file_name in files:
            if "TargetBD" in file_name:
                sw_name = file_name.split("TargetBD_")[-1].split(".xml")[0]
                if sw_name.split("_", 3)[2] in ["9990", "9999"]:
                    return "_".join(["SBTS00", sw_name.split("_", 1)[1]])
                return sw_name

    @staticmethod
    def prepare_sw_iterator(node_tech):
        var_names = ["{}_TARGET_T1_SW_PATH".format(node_tech),
                     "{}_TARGET_T2_SW_PATH".format(node_tech), "{}_TARGET_SW_PATH".format(node_tech), ]
        sw_list = [(uuf_rfrl_update.get_sw_name_from_sw_package(robot_var(var)), robot_var(var)) for var in var_names]
        set_robot_test_variable("{}_SW_ITERATOR".format(node_tech), cycle(sw_list))
